import { jsonLdDocument } from '@/lib/structured-data'

/**
 * Emits a JSON-LD `@graph` script tag.
 *
 * `JSON.stringify` output is injected through `dangerouslySetInnerHTML`, which
 * is the only correct way to write a `<script type="application/ld+json">` in
 * React — JSX would HTML-escape the quotes and produce invalid JSON.
 *
 * It is safe here, and ONLY here, because the content is generated by
 * `JSON.stringify` from our own objects rather than taken from stored text.
 * `stringify` escapes the characters that would close the tag, so no value can
 * break out of the script element.
 */
export function JsonLd({ nodes }: { nodes: Array<Record<string, unknown>> }) {
  if (nodes.length === 0) return null

  return (
    <script
      type="application/ld+json"
      dangerouslySetInnerHTML={{ __html: jsonLdDocument(nodes) }}
    />
  )
}
